[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Activate', 'Deactivate', 'Status', 'Restore')]
    [string]$Mode
)

$ErrorActionPreference = 'Stop'
$root = 'E:\codex-LOOP\codex-loop-s-f2'
$tool = Join-Path $root 'harness\global_desktop_mode.py'
$python = 'E:\codex-LOOP\venv\Scripts\python.exe'
$codexHome = Join-Path $env:USERPROFILE '.codex'

if (-not (Test-Path -LiteralPath $python -PathType Leaf)) {
    $python = (Get-Command py.exe -ErrorAction Stop).Source
    $pythonArgs = @('-3')
}
else {
    $pythonArgs = @()
}

$action = switch ($Mode) {
    'Activate' { 'activate' }
    'Deactivate' { 'deactivate' }
    'Restore' { 'restore' }
    default { 'status' }
}

& $python @pythonArgs $tool $action --root $root --codex-home $codexHome
if ($LASTEXITCODE -ne 0) {
    throw "Codex LOOP global mode action failed: $Mode"
}

if ($Mode -eq 'Activate') {
    Write-Host 'LOOP mode is active for every newly started or resumed Desktop task, regardless of project.'
}
elseif ($Mode -eq 'Deactivate') {
    Write-Host 'LOOP mode is inactive. New or resumed Desktop tasks will not inherit LOOP orchestration.'
}
elseif ($Mode -eq 'Restore') {
    Write-Host 'The pre-install global AGENTS.md and hooks.json were restored from the verified backup.'
}

